<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('cars.php');verifyCsrf();$id=(int)($_POST['id']??0);try{$pdo=db();$q=$pdo->prepare('SELECT image_url FROM cars WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c)throw new RuntimeException('Vehicle not found.');$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE car_id=?');$q->execute([$id]);$has=(int)$q->fetchColumn();if($has){$pdo->prepare('UPDATE cars SET active=0 WHERE id=?')->execute([$id]);flash('success','Vehicle has bookings, so it was hidden instead of deleted.');}else{$imgs=$pdo->prepare('SELECT image_url FROM car_images WHERE car_id=?');$imgs->execute([$id]);foreach($imgs->fetchAll() as $i)deleteImageFile($i['image_url']);deleteImageFile($c['image_url']);$pdo->prepare('DELETE FROM cars WHERE id=?')->execute([$id]);flash('success','Vehicle deleted.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect('cars.php');